{"command":"node -e "
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lerp=(a,b,t)=>a+(b-a)*t;
const smooth=(a,b,x)=>{const t=clamp((x-a)/(b-a),0,1);return t*t*(3-2*t)};
let x=-4,y=0,th=0,s=0; const pts=[[x,y,th,s]];
const Rof=t=> t<0.35?lerp(54,19,smooth(0,0.35,t)) : t<1.9?lerp(19,17.5,smooth(0.35,1.9,t)) : t<2.88?lerp(17.5,31,smooth(1.9,2.88,t)) : lerp(31,85,smooth(2.88,2.96,t));
const thMax=2.96;
while(th<thMax){ const R=Rof(th); const dth=Math.min(0.09/R,thMax-th); const ds=R*dth; const tm=th+dth/2; th+=dth; x+=Math.cos(tm)*ds; y+=Math.sin(tm)*ds; s+=ds; pts.push([x,y,th,s]); }
const maxX=Math.max(...pts.map(p=>p[0]));
const at=deg=>pts.find(p=>p[2]>=deg*Math.PI/180);
const s150=at(150)[3], sEnd=s;
console.log('lip x,y,thDeg=',x.toFixed(1),y.toFixed(1),(th*57.3).toFixed(0),'curveLen=',s.toFixed(1),'maxX=',maxX.toFixed(1));
console.log('at90', at(90).map(v=>+v.toFixed(1)), 'at150', at(150).map(v=>+v.toFixed(1)), 'at158', at(158).map(v=>+v.toFixed(1)), 'at165', at(165).map(v=>+v.toFixed(1)));
console.log('ceiling arc >=150deg length=', (sEnd-s150).toFixed(1));
console.log('height/carLengths=', (y/4.5).toFixed(1));
"","description":"Numerically verify new ramp profile"}

